import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.CHv3BZZk.js";const g=JSON.parse('{"title":"架构设计（architecture.md）","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1792210764000}'),n={name:"architecture.md"};function l(o,e,d,c,r,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="架构设计-architecture-md" tabindex="-1">架构设计（architecture.md） <a class="header-anchor" href="#架构设计-architecture-md" aria-label="Permalink to &quot;架构设计（architecture.md）&quot;">​</a></h1><h2 id="_1-总体架构" tabindex="-1">1. 总体架构 <a class="header-anchor" href="#_1-总体架构" aria-label="Permalink to &quot;1. 总体架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ apps/installer │ apps/uninstaller   （薄二进制：加载配置→跑壳） │</span></span>
<span class="line"><span>└──────────────┬───────────────────────────┬──────────────────┘</span></span>
<span class="line"><span>               ▼                           ▼</span></span>
<span class="line"><span>┌──────────────────────────┐   ┌──────────────────────────────┐</span></span>
<span class="line"><span>│  crates/ui-adapter       │   │  crates/flow-engine           │</span></span>
<span class="line"><span>│  egui 适配层：固定窗口壳、 │   │  安装流程引擎：状态机、动作集、 │</span></span>
<span class="line"><span>│  节点树→egui 渲染、主题、  │◄──┤  执行器（后台线程）、回滚、    │</span></span>
<span class="line"><span>│  字体、事件→流程分发      │   │  安装/卸载清单读写、平台实现    │</span></span>
<span class="line"><span>└───────────┬──────────────┘   └──────────────────────────────┘</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  crates/semantic-ui  语义标签核心：词法/语法解析、AST、       │</span></span>
<span class="line"><span>│  固定画布布局引擎、组件模型、主题令牌（不依赖 egui，可单测）   │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>分层原则</strong>：</p><ul><li><code>semantic-ui</code> 与 <code>flow-engine</code> <strong>零 GUI 依赖</strong>——纯逻辑，可 headless 单测，并支撑 <code>--dry-run</code> 无 GUI 全流程验证。</li><li><code>ui-adapter</code> 是<strong>唯一</strong>触碰 egui 的层。</li><li>安装器与卸载器共用同一 <code>ui-adapter</code> 壳 + 同一 <code>flow-engine</code>，仅以 <code>Mode::{Install, Uninstall}</code> + 配置区分——即需求中的&quot;统一底层架构&quot;。</li></ul><h2 id="_2-固定尺寸取舍-重要" tabindex="-1">2. 固定尺寸取舍（重要） <a class="header-anchor" href="#_2-固定尺寸取舍-重要" aria-label="Permalink to &quot;2. 固定尺寸取舍（重要）&quot;">​</a></h2><p>需求中的&quot;窗口尺寸灵活配置与动态调整&quot;按最终裁定实现为：<strong>尺寸可配置、运行时固定</strong>。</p><ul><li>权威尺寸来源：语义标记 <code>&lt;window width height&gt;</code>；<code>install.toml</code> 的 <code>[window]</code> 段为可选覆盖。</li><li>运行时：<code>eframe::ViewportBuilder::with_inner_size([w, h]).with_resizable(false).with_maximized(false)</code>， 窗口不可拖动缩放、不可最大化。</li><li>画布尺寸为<strong>逻辑单位</strong>：在高 DPI 显示器上，egui 按系统缩放（native pixels-per-point）把逻辑画布 放大为物理像素渲染，窗口物理尺寸 = 逻辑 × 系统缩放；布局始终以逻辑画布为权威，所见即所得。</li><li>布局引擎基于固定画布（fixed canvas）确定性计算：解析期即可算出每个节点的矩形， 无需测量反馈循环；内容超出画布时产生<strong>解析期告警</strong>。</li><li>明确不做：滚动、响应式 / 自适应重排。未来版本可在此模型上扩展响应式布局，不推翻现有模型。</li></ul><h2 id="_3-semantic-ui-标记语言与布局" tabindex="-1">3. semantic-ui：标记语言与布局 <a class="header-anchor" href="#_3-semantic-ui-标记语言与布局" aria-label="Permalink to &quot;3. semantic-ui：标记语言与布局&quot;">​</a></h2><h3 id="_3-1-词法-语法" tabindex="-1">3.1 词法 / 语法 <a class="header-anchor" href="#_3-1-词法-语法" aria-label="Permalink to &quot;3.1 词法 / 语法&quot;">​</a></h3><p>手写词法 + 递归下降解析器（零第三方依赖）。语法与 HTML 类似：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;window title=&quot;Demo&quot; width=&quot;900&quot; height=&quot;620&quot; theme=&quot;light&quot;&gt;</span></span>
<span class="line"><span>  &lt;page id=&quot;welcome&quot; title=&quot;欢迎&quot;&gt;</span></span>
<span class="line"><span>    &lt;row&gt; &lt;text size=&quot;24&quot;&gt;你好&lt;/text&gt; &lt;/row&gt;</span></span>
<span class="line"><span>  &lt;/page&gt;</span></span>
<span class="line"><span>&lt;/window&gt;</span></span></code></pre></div><p>支持：元素、<code>key=&quot;value&quot;</code> 属性、文本内容、<code>&lt;!-- 注释 --&gt;</code>、自闭合标签、 裸属性（值为 true）、<code>#rgb / #rrggbb</code> 颜色、实体解码（<code>&amp;lt; &amp;gt; &amp;amp; &amp;quot; &amp;#39; &amp;nbsp;</code>）。 解析错误带行列号；未知标签硬错误；重复属性警告。</p><h3 id="_3-2-布局引擎-固定画布" tabindex="-1">3.2 布局引擎（固定画布） <a class="header-anchor" href="#_3-2-布局引擎-固定画布" aria-label="Permalink to &quot;3.2 布局引擎（固定画布）&quot;">​</a></h3><ul><li>画布 = <code>&lt;window&gt;</code> 声明的宽高。</li><li><code>row</code>（水平）/ <code>column</code>（垂直）流式排列，支持： <ul><li>固定像素尺寸（<code>width=&quot;240&quot;</code> / <code>height=&quot;36&quot;</code>）；</li><li><code>weight=&quot;n&quot;</code> 按比例分配剩余空间；</li><li><code>fill</code>（缺省）占满剩余空间；</li><li><code>spacer</code> 弹性占位（可声明 <code>width</code>/<code>height</code> 固定间隙）；</li><li><code>gap</code>（间距）、<code>padding</code>（内边距）、<code>align</code>（Start / Center / End，作用于分配后的剩余空间）。</li></ul></li><li>容器跨轴默认撑满；文本尺寸由 <code>Measurer</code> 抽象提供（GUI 层用真实字体度量，测试用桩）。</li><li><strong>图层</strong>：<code>&lt;page&gt;</code> 直接子节点为 <code>&lt;layer&gt;</code> 时，每个图层在<strong>同一整幅画布</strong>上独立布局， 渲染按声明顺序（z 序）叠加；<code>bg</code> 属性可为图层铺背景色。非 layer 直接子节点忽略并告警，禁止嵌套图层。</li><li><strong>i18n</strong>：<code>lang/{locale}.toml</code> 键值资源，布局前按当前语言把 <code>i18n</code> 键文本替换进节点 （未命中回退默认文本）；<code>select id=&quot;locale&quot;</code> 运行时切换即整页重布局重渲染。</li><li><strong>动画</strong>：<code>animate=&quot;&lt;kind&gt; &lt;dur&gt;ms [infinite] [delay &lt;n&gt;ms]&quot;</code> 为<strong>渲染期</strong>时间插值 （fade/slide/spin/pulse/scale-in），不侵入布局矩形；一次性动画随页面进入播放。</li><li>输出 <code>PageModel { id, title, nodes, rects, warnings, canvas, layers }</code>——每个控件一个确定矩形。</li></ul><h3 id="_3-3-组件模型与校验" tabindex="-1">3.3 组件模型与校验 <a class="header-anchor" href="#_3-3-组件模型与校验" aria-label="Permalink to &quot;3.3 组件模型与校验&quot;">​</a></h3><p><code>UiState</code> 保存输入 / 复选 / 单选 / 下拉的运行时值；<code>page_valid()</code> 判定页面是否满足 <code>required</code> 约束（必填输入非空、必选复选框已勾选）。<code>next / install / uninstall</code> 类前进按钮 在页面未通过校验时自动禁用（渲染层直接绘制为禁用态）。</p><h2 id="_4-flow-engine-安装流程引擎" tabindex="-1">4. flow-engine：安装流程引擎 <a class="header-anchor" href="#_4-flow-engine-安装流程引擎" aria-label="Permalink to &quot;4. flow-engine：安装流程引擎&quot;">​</a></h2><h3 id="_4-1-清单模型-install-toml" tabindex="-1">4.1 清单模型（install.toml） <a class="header-anchor" href="#_4-1-清单模型-install-toml" aria-label="Permalink to &quot;4.1 清单模型（install.toml）&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]      </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">name / id / version / publisher / homepage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">window</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">width / height / resizable(false) / theme   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可选覆盖</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]    pages = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;welcome&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...]                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 页面顺序</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">install]</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  install_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$LOCALAPPDATA/Demo App&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 目录模板</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  copy_uninstaller = true                               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 复制卸载器进安装目录</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  items: copy-dir | copy-file | create-dir | write-file</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  shortcuts: name / target / args / icon / dir(desktop|start-menu)</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  registry: uninstall_key + values(path/name/value)</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  run_after: cmd / args / wait</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">[uninstall]</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  keep_user_data = [...]       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 卸载保留路径（应位于安装目录之外）</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">  remove_shortcuts / remove_registry</span></span></code></pre></div><p>路径占位符：<code>$LOCALAPPDATA $PROGRAMFILES $INSTALL_DIR $HOME $TEMP $EXEDIR</code>， 由 <code>platform::ResolveCtx</code> 按平台解析。</p><h3 id="_4-2-动作集与执行器" tabindex="-1">4.2 动作集与执行器 <a class="header-anchor" href="#_4-2-动作集与执行器" aria-label="Permalink to &quot;4.2 动作集与执行器&quot;">​</a></h3><ul><li>动作：<code>CopyDir / CopyFile / CreateDir / WriteFile / RemovePath / RemoveIfEmpty / CreateShortcut / RemoveShortcut / RegWrite / RegDelete / Run / CopyUninstaller</code>。</li><li>执行器在<strong>后台线程</strong>逐动作执行，经 <code>crossbeam-channel</code> 上报 <code>ProgressEvent { done, total, message }</code>；UI 线程轮询重绘进度页。</li><li>取消：<code>Arc&lt;AtomicBool&gt;</code> 协作式取消。</li><li><strong>回滚</strong>：任一动作失败或取消时，按创建顺序逆序删除已创建的文件 / 目录 / 快捷方式 / 注册表值 / 注册表键，保证安装失败不留残留。</li><li>全程写 <code>install.log</code>（动作描述 + 结果 + 耗时）。</li></ul><h3 id="_4-3-安装记录-uninstall-json" tabindex="-1">4.3 安装记录（uninstall.json） <a class="header-anchor" href="#_4-3-安装记录-uninstall-json" aria-label="Permalink to &quot;4.3 安装记录（uninstall.json）&quot;">​</a></h3><p>安装成功后写入：安装目录 <code>uninstall.json</code> + 用户级副本 <code>%LOCALAPPDATA%/&lt;app_id&gt;/uninstall.json</code>，供卸载器定位。记录包含： app 信息、安装目录、创建的文件 / 目录 / 快捷方式 / 注册表值、卸载策略、 卸载器路径、<strong>完整清单（flow）</strong>。</p><h3 id="_4-4-平台能力-cfg-门控" tabindex="-1">4.4 平台能力（cfg 门控） <a class="header-anchor" href="#_4-4-平台能力-cfg-门控" aria-label="Permalink to &quot;4.4 平台能力（cfg 门控）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>Windows</th><th>macOS / Linux</th></tr></thead><tbody><tr><td>注册表读写</td><td><code>winreg</code> 实现</td><td>no-op（记录日志）</td></tr><tr><td>.lnk 快捷方式</td><td><code>windows</code> crate COM（<code>ShellLink</code> + <code>IPersistFile</code>）</td><td><code>.desktop</code>（Linux）/ <code>.command</code>（macOS）</td></tr><tr><td>卸载登记</td><td>HKCU「添加 / 删除程序」</td><td>no-op</td></tr><tr><td>用户级记录副本</td><td><code>%LOCALAPPDATA%</code></td><td><code>~/.local/share</code>（dirs）</td></tr></tbody></table><h3 id="_4-5-状态机" tabindex="-1">4.5 状态机 <a class="header-anchor" href="#_4-5-状态机" aria-label="Permalink to &quot;4.5 状态机&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Idle → Validating（构建动作计划）→ Executing（后台）→ Progress（进度轮询）</span></span>
<span class="line"><span>     → Success（写记录 / 注册卸载入口） | Failed（回滚） | Cancelled（回滚）</span></span></code></pre></div><h2 id="_5-ui-adapter-egui-适配层" tabindex="-1">5. ui-adapter：egui 适配层 <a class="header-anchor" href="#_5-ui-adapter-egui-适配层" aria-label="Permalink to &quot;5. ui-adapter：egui 适配层&quot;">​</a></h2><ul><li><strong>固定窗口壳</strong>：尺寸仅来自配置；<code>with_resizable(false)</code> + 禁最大化。</li><li><strong>非系统标题栏模式（--no-titlebar）</strong>：<code>with_decorations(false)</code> 去掉原生标题栏与边框， 由引擎在客户区顶部自绘 32px 标题栏条（应用名 + 最小化 / 关闭矢量按钮 + 空白区拖动 <code>StartDrag</code>）； 画布尺寸不变，标题栏条覆盖画布顶部（页面默认 padding ≥ 40 不受遮挡）。安装器 / 卸载器均支持。</li><li><strong>透明标题栏（--titlebar-transparent）</strong>：隐式启用 <code>--no-titlebar</code>，进一步省略标题栏条 的背景块与分隔线——条区域完全透明，可透出 <code>&lt;layer&gt;</code> 背景图；应用名文字与最小化 / 关闭图标 干净绘制（不叠加阴影），可读性交由开发者通过半透明图层（<code>layer bg=&quot;#rrggbbaa&quot;</code>）自行控制； 按钮 hover 仍显示背景块（最小化浅灰 / 关闭红色）。</li><li><strong>渲染</strong>：<code>PageModel</code> 节点树 → egui 组件——自绘按钮（圆角 / 主色 / 悬停 / 禁用）、 自绘单选与进度条、<code>TextEdit</code> / <code>Checkbox</code> / <code>ComboBox</code> / <code>Texture</code>（PNG banner）映射； 图层按 z 序整层渲染；动画用 <code>Painter</code> 的透明度 / 位移 / 旋转（<code>RectShape::with_angle</code>）/ 缩放实现。 图标一律矢量绘制（<code>egui::Painter</code>），不使用 emoji / 表情字符。</li><li><strong>字体</strong>：探测系统 CJK 字体注入 <code>FontDefinitions</code>（Windows msyh / macOS PingFang / Linux NotoSansCJK），缺失时降级并告警。</li><li><strong>主题</strong>：语义令牌（bg / panel / text / primary / accent / danger / radius / spacing）→ <code>egui::Visuals</code> + <code>Style</code>（按 <code>egui::Theme::Light/Dark</code> 设置）；<code>--theme light|dark</code> 可覆盖。</li><li><strong>事件</strong>：按钮 <code>action</code> → <code>events::handle_click</code> 分发：<code>next / back / cancel / install / uninstall / finish / goto / custom</code>；<code>link</code> 用系统默认浏览器打开 URL；页面标题同步窗口标题。</li><li><strong>关闭策略</strong>：工作期间收到关闭请求 → 先取消后台线程并等待回滚完成，再允许退出。</li></ul><h2 id="_6-可靠性设计-无泄漏、无崩溃" tabindex="-1">6. 可靠性设计（无泄漏、无崩溃） <a class="header-anchor" href="#_6-可靠性设计-无泄漏、无崩溃" aria-label="Permalink to &quot;6. 可靠性设计（无泄漏、无崩溃）&quot;">​</a></h2><ol><li><strong>0 unsafe</strong>（应用代码）：仅 <code>flow-engine/platform/windows.rs</code> 的 COM 互操作含两处 经审计的 <code>unsafe</code>（<code>ShellLink</code> 创建与 <code>QueryInterface</code>），已逐行注释说明。</li><li>所有权 / RAII 保证无泄漏；egui 纹理句柄随 <code>AssetCache</code> 生命周期释放。</li><li>UI 路径<strong>禁止</strong> <code>unwrap / expect</code>；标记 / 清单解析错误以友好错误页呈现（含行列号）， 进程不静默崩溃；<code>main</code> 全程返回 <code>ExitCode</code>。</li><li>后台线程与 UI 线程仅经 channel 通信，无跨线程共享可变状态。</li><li>全局 panic hook 记日志后优雅退出（eframe 默认行为 + 错误页兜底）。</li></ol><h2 id="_7-技术栈与版本" tabindex="-1">7. 技术栈与版本 <a class="header-anchor" href="#_7-技术栈与版本" aria-label="Permalink to &quot;7. 技术栈与版本&quot;">​</a></h2><ul><li>Rust stable ≥ 1.92（eframe 0.35 MSRV）；本工程锁定 <code>rust-toolchain.toml</code>。</li><li><code>eframe / egui 0.35</code>（注意 0.35 为 Ui 中心化 API：<code>App::ui(&amp;mut Ui, &amp;mut Frame)</code>、 <code>ctx.style_of/set_style_of(egui::Theme, …)</code>、<code>Rect</code> 字段私有化等）。</li><li><code>serde / toml / serde_json</code>、<code>crossbeam-channel</code>、<code>rfd</code>（目录选择）、<code>image</code>（PNG）、 <code>winreg</code>、<code>windows</code>（仅 Windows target）、<code>env_logger</code>、<code>dirs</code>。</li><li>可选 <code>native-core</code> feature（C/C++ 原生核心扩展点）<strong>默认关闭</strong>——本引擎全 Rust 实现， 预留 FFI 位置供性能敏感模块接入，不引入 C 工具链依赖。</li></ul><h2 id="_8-目录结构" tabindex="-1">8. 目录结构 <a class="header-anchor" href="#_8-目录结构" aria-label="Permalink to &quot;8. 目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>crates/semantic-ui/src/   lib lexer parser ast layout widget theme</span></span>
<span class="line"><span>crates/flow-engine/src/   lib spec actions executor manifest dry_run platform/{mod,windows,posix}</span></span>
<span class="line"><span>crates/ui-adapter/src/    lib app render theme fonts assets events</span></span>
<span class="line"><span>apps/installer/src/       main.rs（参数解析 / 清单加载 / 固定窗口运行）</span></span>
<span class="line"><span>apps/uninstaller/src/     main.rs（记录定位 / 内置默认界面 / 运行）</span></span>
<span class="line"><span>examples/demo/            app.ui install.toml uninstall.ui resources/ README.md</span></span></code></pre></div>`,37)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
